246		writeRawDiskFile(t, dir, raw)
247		s, err := Open(dir)
248		if err != nil {
249			t.Fatalf("明确保存的负数与正数限值应正常打开: %v", err)
250		}
251		defer s.Close()
252		smp, err := s.Confirm("S1")
253		if err != nil {
254			t.Fatalf("Confirm: %v", err)
255		}
256		rs := map[string]ItemResult{}
257		for _, r := range smp.Results {
258			rs[r.Item] = r
259		}
260		if ph := rs[openPH]; ph.Limit != -1 || ph.Exceeded {
261			t.Fatalf("-2 ≤ -1 应达标: %+v", ph)
262		}
263		if cod := rs["COD"]; cod.Limit != 30 || cod.Exceeded {
264			t.Fatalf("30 ≤ 30 应达标: %+v", cod)
265		}
266	}
267	
268	// 完整的多版本限值即使保存顺序不同也正常打开，确认时仍按采样时间选取当时
269	// 已生效的最近一版，恰好等于生效时刻采用新版。
270	func TestOpenCompleteMultiVersionLimitsUnordered(t *testing.T) {
271		dir := t.TempDir()
272		raw := `{
273	  "points": {"P1": {"id": "P1", "name": "一号取水口"}},
274	  "limits": {"P1-pH": [
275	    {"pointId": "P1", "item": "pH", "value": 6, "effective": "` + at(10, 0).Format(time.RFC3339Nano) + `"},
276	    {"pointId": "P1", "item": "pH", "value": 9, "effective": "` + at(1, 0).Format(time.RFC3339Nano) + `"},
277	    {"pointId": "P1", "item": "pH", "value": 7, "effective": "` + at(5, 0).Format(time.RFC3339Nano) + `"}
278	  ]},
279	  "samples": {
280	    "S-MID": {
281	      "id": "S-MID", "pointId": "P1",
282	      "sampledAt": "` + at(6, 0).Format(time.RFC3339Nano) + `",
283	      "measurements": [{"item": "pH", "value": 8}],
284	      "status": "pending"
285	    },
286	    "S-AT": {
287	      "id": "S-AT", "pointId": "P1",
288	      "sampledAt": "` + at(10, 0).Format(time.RFC3339Nano) + `",
289	      "measurements": [{"item": "pH", "value": 8}],
290	      "status": "pending"
291	    }
292	  }
293	}`
294		writeRawDiskFile(t, dir, raw)
295		s, err := Open(dir)
296		if err != nil {
297			t.Fatalf("完整的乱序多版本限值应正常打开: %v", err)
298		}
299		defer s.Close()
300		mid, err := s.Confirm("S-MID")
301		if err != nil {
302			t.Fatalf("Confirm S-MID: %v", err)
303		}
304		if r := mid.Results[0]; r.Limit != 7 || !r.LimitEffective.Equal(at(5, 0)) || !r.Exceeded {
305			t.Fatalf("9/6 采样应取 9/5 生效的 7、8 > 7 超标: %+v", r)
306		}
307		atBoundary, err := s.Confirm("S-AT")
308		if err != nil {
309			t.Fatalf("Confirm S-AT: %v", err)
310		}
311		if r := atBoundary.Results[0]; r.Limit != 6 || !r.LimitEffective.Equal(at(10, 0)) || !r.Exceeded {
312			t.Fatalf("恰好生效时刻应采用新版 6: %+v", r)
313		}
314	}
315	
316	// 缺数值的限值与完整的已确认结论、作废记录同处一个文件：整次打开失败，
317	// 历史依据不因这次读取核对而改选限值或重新判定——打开根本不会成功。
318	func TestOpenLimitMissingValueWithConfirmedAndVoidedSamples(t *testing.T) {
319		dir := t.TempDir()
320		raw := `{
321	  "points": {"P1": {"id": "P1", "name": "一号取水口"}},
322	  "limits": {"P1-pH": [{"pointId": "P1", "item": "pH", "effective": "` +
323			openEff().Format(time.RFC3339Nano) + `"}]},
324	  "samples": {
325	    "SC": {
326	      "id": "SC", "pointId": "P1",
327	      "sampledAt": "` + at(5, 0).Format(time.RFC3339Nano) + `",
328	      "measurements": [{"item": "pH", "value": 9}],
329	      "status": "confirmed", "exceeded": true,
330	      "results": [{"item": "pH", "value": 9, "limit": 8, "limitEffective": "` +
331			openEff().Format(time.RFC3339Nano) + `", "exceeded": true}]
332	    },
333	    "SV": {
334	      "id": "SV", "pointId": "P1",
335	      "sampledAt": "` + at(6, 0).Format(time.RFC3339Nano) + `",
336	      "measurements": [{"item": "pH", "value": 9}],
337	      "status": "voided", "voidReason": "复测确认样品污染", "exceeded": true,
338	      "results": [{"item": "pH", "value": 9, "limit": 8, "limitEffective": "` +
339			openEff().Format(time.RFC3339Nano) + `", "exceeded": true}]
340	    }
341	  }
342	}`
343		writeRawDiskFile(t, dir, raw)
344		assertOpenRejectsLimitValue(t, dir, "P1", openPH, openEff())
345	}
346	
347	// 没有登记限值的数据照常打开：空数据、只有采样点或只有样品的数据都不受
348	// 这条核对影响；后续样品缺少适用上限时仍按原有行为在确认时拒绝。
349	func TestOpenNoRegisteredLimitsStillOpens(t *testing.T) {
350		// 只有采样点、没有任何限值与样品。
351		dir := t.TempDir()
352		writeRawDiskFile(t, dir, `{"points": {"P1": {"id": "P1", "name": "一号取水口"}}}`)
353		s, err := Open(dir)
354		if err != nil {
355			t.Fatalf("没有登记限值的数据应正常打开: %v", err)
356		}
357		defer s.Close()
358	
359		// 录入一份没有适用上限的样品：打开不受影响，确认时仍按原有行为拒绝。
360		mustSample(t, s, "S1", "P1", at(10, 0), Measurement{Item: openPH, Value: 7})
361		if err := s.Close(); err != nil {
362			t.Fatalf("Close: %v", err)
363		}
364		s2, err := Open(dir)
365		if err != nil {
366			t.Fatalf("有样品但没有登记限值的数据应正常打开: %v", err)
367		}
368		defer s2.Close()
369		if _, err := s2.Confirm("S1"); !errors.Is(err, ErrMissingLimit) {
370			t.Fatalf("缺少适用上限仍应在确认时拒绝，got %v", err)
371		}
372	}
373	
374	// 限值归属沿用现有行为：共用旧版存储键的不同（采样点，项目）组合各自成组，
375	// 其中一组缺少数值时按该组自身的采样点与项目报告，不误伤另一组。
376	func TestOpenLimitMissingValueWithinOldCollidedKey(t *testing.T) {
377		dir := t.TempDir()
378		zeroPoint := "P\x00A"
379		zeroItem := "A\x00B"
380		oldKey := zeroPoint + "\x00" + "B"
381		if oldKey != "P"+"\x00"+zeroItem {
382			t.Fatal("测试前提：两个组合应拼出同一个旧键")
383		}
384		// 完整的一组与缺数值的一组共用同一个旧版存储键。先经 Go 结构体序列化
385		// 落盘，再按通用 JSON 结构把第二条的 value 字段删掉，构造出缺少数值的
386		// 限值记录（含 U+0000 的文本落盘时被转义，直接拼原始字符串不可靠）。
387		writeDiskFile(t, dir, diskState{
388			Points: map[string]SamplingPoint{
389				"P": {ID: "P", Name: "普通编号"},
390			},
391			Limits: map[string][]Limit{
392				oldKey: {
393					{PointID: "P", Item: zeroItem, Value: 5, Effective: openEff()},
394					{PointID: zeroPoint, Item: "B", Effective: openEff()},
395				},
396			},
397		})
398		data, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
399		if err != nil {
400			t.Fatalf("read data file: %v", err)
401		}
402		var doc map[string]interface{}
403		if err := json.Unmarshal(data, &doc); err != nil {
404			t.Fatalf("unmarshal data file: %v", err)
405		}
406		versions, ok := doc["limits"].(map[string]interface{})[oldKey].([]interface{})
407		if !ok || len(versions) != 2 {
408			t.Fatalf("测试前提：应有两版限值记录在同一旧键下: %s", data)
409		}
410		second, ok := versions[1].(map[string]interface{})
411		if !ok || second["pointId"] != zeroPoint || second["item"] != "B" {
412			t.Fatalf("测试前提：第二版应是 %q/B: %s", zeroPoint, data)
413		}
414		delete(second, "value")
415		raw, err := json.Marshal(doc)
416		if err != nil {
417			t.Fatalf("remarshal data file: %v", err)
418		}
419		writeRawDiskFile(t, dir, string(raw))
420		assertOpenRejectsLimitValue(t, dir, zeroPoint, "B", openEff())
421	}
